import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");

        // Input length validation
        if (reportType == null || reportType.length() > 64) {
            resp.sendError(400, "Invalid report type");
            return;
        }
        if (startDate == null || !startDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid start date format");
            return;
        }
        if (endDate == null || !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid end date format");
            return;
        }

        // Department parameter is optional, used for filtering
        String deptFilter = "";
        if (department != null && !department.isEmpty()) {
            // Sanitize: remove obvious SQL keywords (basic blocklist)
            String cleaned = department.replaceAll("(?i)(drop|alter|truncate|create)", "");
            deptFilter = " AND department = '" + cleaned + "'";
        }

        String tableName;
        switch (reportType) {
            case "sales": tableName = "quarterly_sales"; break;
            case "inventory": tableName = "warehouse_inventory"; break;
            case "hr": tableName = "employee_records"; break;
            case "finance": tableName = "financial_ledger"; break;
            default:
                resp.sendError(400, "Unknown report type");
                return;
        }

        // Build query - dates are validated by regex above
        String query = "SELECT * FROM " + tableName +
                " WHERE report_date BETWEEN '" + startDate + "' AND '" + endDate + "'" +
                deptFilter +
                " ORDER BY report_date DESC LIMIT 1000";

        log.info("Executing report query for type=" + reportType);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= cols; i++) {
                    row.put(meta.getColumnLabel(i), rs.getObject(i));
                }
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.setCharacterEncoding("UTF-8");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST not supported for reports
        resp.sendError(405, "Use GET for report queries");
    }
}
